PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE products (     id INTEGER PRIMARY KEY AUTOINCREMENT,     name TEXT NOT NULL,     highlight TEXT,     desc TEXT,     img TEXT,     items TEXT,     patent TEXT,     patent_no TEXT , img_home TEXT DEFAULT '', updated_by TEXT, updated_at TEXT);
CREATE TABLE timeline (     id INTEGER PRIMARY KEY AUTOINCREMENT,     year TEXT NOT NULL,     title TEXT NOT NULL,     description TEXT,     future_outlook TEXT , updated_by TEXT, updated_at TEXT);
CREATE TABLE synonyms (   id         INTEGER PRIMARY KEY AUTOINCREMENT,   product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,   say        TEXT NOT NULL, updated_by TEXT, updated_at TEXT,   UNIQUE (product_id, say) );
CREATE TABLE languages (   code       TEXT PRIMARY KEY,    label      TEXT NOT NULL,   is_base    INTEGER NOT NULL DEFAULT 0,     sort_order INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE translations (   id        INTEGER PRIMARY KEY AUTOINCREMENT,   entity    TEXT NOT NULL,          entity_id INTEGER NOT NULL,       field     TEXT NOT NULL,                    lang      TEXT NOT NULL REFERENCES languages(code) ON DELETE CASCADE,   value     TEXT NOT NULL DEFAULT '',   UNIQUE (entity, entity_id, field, lang) );
CREATE TABLE settings (   id           INTEGER PRIMARY KEY AUTOINCREMENT,   key          TEXT NOT NULL UNIQUE,   value        TEXT NOT NULL DEFAULT '',   label        TEXT NOT NULL DEFAULT '',    hint         TEXT NOT NULL DEFAULT '',   translatable INTEGER NOT NULL DEFAULT 0,   sort_order   INTEGER NOT NULL DEFAULT 0 , updated_by TEXT, updated_at TEXT);
CREATE TABLE synonym_suggestions (   id         INTEGER PRIMARY KEY AUTOINCREMENT,   product_id INTEGER NOT NULL,   say        TEXT NOT NULL,   source     TEXT NOT NULL DEFAULT 'ai',   status     TEXT NOT NULL DEFAULT 'pending',   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   UNIQUE (product_id, say) );
CREATE TABLE inquiries (   id         INTEGER PRIMARY KEY AUTOINCREMENT,   company    TEXT NOT NULL DEFAULT '',   email      TEXT NOT NULL DEFAULT '',   phone      TEXT NOT NULL DEFAULT '',   product    TEXT NOT NULL DEFAULT '',   message    TEXT NOT NULL DEFAULT '',   lang       TEXT NOT NULL DEFAULT '',   page       TEXT NOT NULL DEFAULT '',   status     TEXT NOT NULL DEFAULT 'new',   note       TEXT NOT NULL DEFAULT '',   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP , updated_by TEXT, updated_at TEXT);
CREATE TABLE ui_strings (   id    INTEGER PRIMARY KEY AUTOINCREMENT,   zh    TEXT NOT NULL UNIQUE,             page  TEXT NOT NULL DEFAULT '',         note  TEXT NOT NULL DEFAULT '' , hidden INTEGER NOT NULL DEFAULT 0, zh_key TEXT, updated_by TEXT, updated_at TEXT);
CREATE TABLE page_blocks (   id         INTEGER PRIMARY KEY AUTOINCREMENT,   page       TEXT NOT NULL,                       layout     TEXT NOT NULL DEFAULT 'image-right',    eyebrow    TEXT NOT NULL DEFAULT '',            title      TEXT NOT NULL DEFAULT '',   body       TEXT NOT NULL DEFAULT '',   image      TEXT NOT NULL DEFAULT '',          caption    TEXT NOT NULL DEFAULT '',           sort_order INTEGER NOT NULL DEFAULT 0,   visible    INTEGER NOT NULL DEFAULT 1,   created_at TEXT NOT NULL DEFAULT (datetime('now')) , updated_by TEXT, updated_at TEXT);
CREATE TABLE media (   name       TEXT PRIMARY KEY,                 mime       TEXT NOT NULL DEFAULT 'image/webp',   data       TEXT NOT NULL,                    bytes      INTEGER NOT NULL DEFAULT 0,   width      INTEGER NOT NULL DEFAULT 0,   height     INTEGER NOT NULL DEFAULT 0,   created_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE TABLE site_images (   id         INTEGER PRIMARY KEY AUTOINCREMENT,   key        TEXT NOT NULL UNIQUE,   label      TEXT NOT NULL DEFAULT '',   hint       TEXT NOT NULL DEFAULT '',   path       TEXT NOT NULL DEFAULT '',   fallback   TEXT NOT NULL DEFAULT '',   sort_order INTEGER NOT NULL DEFAULT 0,   updated_by TEXT,   updated_at TEXT );
DELETE FROM sqlite_sequence;
CREATE INDEX idx_synonyms_product ON synonyms (product_id);
CREATE INDEX idx_tr_lookup ON translations (entity, lang, entity_id);
CREATE INDEX idx_sugg_status ON synonym_suggestions (status, product_id);
CREATE INDEX idx_inq_status ON inquiries (status, id);
CREATE INDEX idx_ui_page ON ui_strings (page);
CREATE INDEX idx_blocks_page ON page_blocks (page, sort_order);
