INSERT INTO "products" ("id","name","highlight","desc","img","items","patent","patent_no","img_home","updated_by","updated_at") VALUES(1,'Scale Sheet (Tare Sheet)','專利單張抽取設計｜取用便利・不易污染・衛生安心','結合專利技術打造的抽取式 Scale Sheet，突破傳統取用方式的繁瑣與不便。採用貼心的單張抽取設計，取用俐落、操作便利，不僅能提升作業效率、節省取用時間，更能有效控管使用成本。材質強韌、防沾黏且不易受污染，適用於生鮮秤重、餐飲備料、工業分裝及各大商場櫃台等多元作業場景，是追求高效率、衛生與便利性的專業首選。','/media/Scale%20Sheet.webp','專利證書、防沾黏、不受汙染','/media/Patent.webp','','/media/%E5%B0%81%E9%9D%A2-Scale%20Sheet.webp','admin','2026-09-10T06:34:38.990Z');
INSERT INTO "products" ("id","name","highlight","desc","img","items","patent","patent_no","img_home","updated_by","updated_at") VALUES(2,'耐熱袋','食品級，守護食材新鮮與衛生','專為生鮮食品與日常零售打造的優質耐熱袋系列。嚴選食品級合格原料，質地安全、無毒無味，具備極佳的抗拉韌性。提供平裝、捲裝等多樣化規格，搭配耐熱袋、雙道封口食品袋及市場專用袋等多元選擇，有效鎖住食材水分與鮮度，為消費者與商家嚴格把關每一道飲食安全防線。','/media/%E8%94%AC%E6%9E%9C%E8%A2%8B.webp','食品袋、市場袋、冰袋、雙道封口袋','','','/media/%E5%B0%81%E9%9D%A2-%E8%94%AC%E6%9E%9C%E8%A2%8B.webp','admin','2026-09-10T06:40:44.146Z');
INSERT INTO "products" ("id","name","highlight","desc","img","items","patent","patent_no","img_home","updated_by","updated_at") VALUES(3,'清潔袋','強韌耐穿刺、絕不漏水的日常清潔袋首選','依託台塑高品質原料自製優勢，經由嘉義新港廠區自動化精密吹膜與封口技術打造。全系列涵蓋連捲式、單張抽取式及國家環保標章認證清潔袋等多種款式。具備超強的抗拉張力與優異承重力，不論是用於一般家庭日常垃圾清運，或是辦公大樓、餐飲旅宿等高頻率商用場域，皆能輕鬆應對、安心不破漏。','/media/%E6%B8%85%E6%BD%94%E8%A2%8B.webp','連捲、單張抽取、八折袋、環保清潔袋','','','/media/%E5%B0%81%E9%9D%A2-%E6%B8%85%E6%BD%94%E8%A2%8B.webp','admin','2026-09-10T06:42:20.573Z');
INSERT INTO "products" ("id","name","highlight","desc","img","items","patent","patent_no","img_home","updated_by","updated_at") VALUES(4,'拉繩清潔袋','一拉即束口，減少蚊蠅孳生，容量大升級增加 30% 、乾淨不沾手','專為現代便利生活與高效清潔設計的貼心之作。一體成型的堅固拉繩結構，讓您輕鬆一拉即可俐落束口，有效避免清理時垃圾外漏與雙手沾染髒汙的困擾。特殊設計使內部空間有效利用率增加 30% 以上，並能緊密鎖住異味不外散；另提供醫療級與環保拉繩款式，讓居家與商辦環境更顯潔淨衛生。','/media/%E6%8B%89%E7%B9%A9%E8%A2%8B1.webp','拉繩清潔袋、拉繩醫療袋、環保拉繩清潔袋','','','/media/%E5%B0%81%E9%9D%A2-%E6%8B%89%E7%B9%A9%E8%A2%8B.webp','admin','2026-09-10T08:42:03.023Z');
INSERT INTO "products" ("id","name","highlight","desc","img","items","patent","patent_no","img_home","updated_by","updated_at") VALUES(5,'多功能手套','親膚舒適、防護俐落的萬用防護手套','兼具極佳彈性與細緻觸感的多功能手套系列。表面採特殊內壓紋設計，不僅穿脫滑順、不沾黏，更具備良好的防滑抓握力。全系列符合無粉末、無乳膠等友善肌膚標準，無論是用於餐飲調理、食品加工、日常清潔打掃或居家照護，皆能提供全方位且靈活舒適的衛生防護體驗。','/media/%E5%A4%9A%E5%8A%9F%E8%83%BD%E6%89%8B%E5%A5%97.webp','無粉末、無乳膠、內壓紋、易穿脫、彈性優、觸感佳','','','/media/%E5%B0%81%E9%9D%A2-%E5%A4%9A%E5%8A%9F%E8%83%BD%E6%89%8B%E5%A5%97.webp','sales','2026-09-09T04:18:13.332Z');
INSERT INTO "products" ("id","name","highlight","desc","img","items","patent","patent_no","img_home","updated_by","updated_at") VALUES(6,'夾鏈袋','密封緊密，完美保鮮','採用高標準工藝打造的重覆使用夾鏈袋系列。袋身厚實、手感紮實，搭配密合度極佳的雙軌或單軌夾鏈結構，具備優異的氣密與防潮表現。不論是生鮮食材冷凍保鮮、日常小物分類收納，或是工業零件包裝，皆能提供卓越的密封保護，支援多次重複開合依然緊密如初。','/media/%E5%A4%BE%E9%8F%88%E8%A2%8B.webp','密實袋、冷凍袋、由任袋、立式夾鏈袋(可直立)','','','/media/%E5%B0%81%E9%9D%A2-%E5%A4%BE%E9%8F%88%E8%A2%8B.webp','admin','2026-09-10T06:49:53.851Z');
INSERT INTO "products" ("id","name","highlight","desc","img","items","patent","patent_no","img_home","updated_by","updated_at") VALUES(7,'遮蔽防塵膠帶','施工裝潢與日常防塵的省時利器','集膠帶與防塵膜於一體的便利防護方案。專為室內裝潢、噴漆粉刷、居家裝修及醫療消毒防護設計，能夠快速且大面積地覆蓋並保護傢俱、地板與牆面免受粉塵、油漆噴濺汙染。黏貼穩固且撕除不留殘膠，大幅簡化施工前的遮蔽前置作業，兼具高效率與完美防護效果。','/media/%E5%8F%B0%E5%A1%91%E9%81%AE%E8%94%BD%E9%98%B2%E5%A1%B5%E8%86%A0%E5%B8%B6.webp','遮蔽保護、消毒防護、覆蓋防塵、施工便利','','','/media/%E5%B0%81%E9%9D%A2-%E5%8F%B0%E5%A1%91%E9%81%AE%E8%94%BD%E9%98%B2%E5%A1%B5%E8%86%A0%E5%B8%B6.webp','sales','2026-09-09T04:17:46.962Z');
INSERT INTO "timeline" ("id","year","title","description","future_outlook","updated_by","updated_at") VALUES(1,'1983','台塑塑膠加工組，於高雄前鎮廠起步','高雄前鎮廠開始生產購物袋，開啟塑膠袋製造歷程。','','admin','2026-09-10T07:16:58.341Z');
INSERT INTO "timeline" ("id","year","title","description","future_outlook","updated_by","updated_at") VALUES(2,'1984','耐熱袋、清潔袋加入產品線','高雄前鎮廠開始生產耐熱袋、清潔袋，產品線逐步擴展。','','admin','2026-09-10T07:17:29.672Z');
INSERT INTO "timeline" ("id","year","title","description","future_outlook","updated_by","updated_at") VALUES(3,'1989','新港廠整地擴建','建立後續聚乙烯薄膜與袋品生產基地。','',NULL,NULL);
