INSERT INTO "timeline" ("id","year","title","description","future_outlook","updated_by","updated_at") VALUES(6,replace('1990s\n–2000s','\n',char(10)),'跨海技術合作，建立長期默契','深化海外(美國)市場連結，累積跨國製造與品質管理經驗。','',NULL,NULL);
INSERT INTO "timeline" ("id","year","title","description","future_outlook","updated_by","updated_at") VALUES(7,'2004','高雄前鎮廠遷廠合併','整合生產線至新港廠，提升生產規模與效率。','',NULL,NULL);
