INSERT INTO "timeline" ("id","year","title","description","future_outlook","updated_by","updated_at") VALUES(9,'2014','台塑塑膠加工組改組，加入美國 INTEPLAST GROUP，臺灣營德股份有限公司正式成立','正式成立臺灣營德，融合台塑扎實根基與美國集團資源，邁向全新紀元。','',NULL,NULL);
INSERT INTO "timeline" ("id","year","title","description","future_outlook","updated_by","updated_at") VALUES(10,'2015','越南營德公司成立','拓展東南亞生產與服務據點，滿足全球客戶需求。','','admin','2026-09-10T07:19:22.706Z');
INSERT INTO "timeline" ("id","year","title","description","future_outlook","updated_by","updated_at") VALUES(12,'2020','開發醫療點滴袋外袋',replace('因應醫療用袋需求增加，完成點滴袋外袋開發。\n','\n',char(10)),'','admin','2026-09-10T07:21:08.731Z');
INSERT INTO "timeline" ("id","year","title","description","future_outlook","updated_by","updated_at") VALUES(13,'2026','把製造能力，推向下一個可能',replace('持續深化功能性薄膜、醫療包裝與永續產品，讓新港及越南基地以更靈活的技術與更穩定的品質，服務下一階段的市場需求。\n','\n',char(10)),'邁向 AI 智慧製造與全循環經濟，打造次世代綠色企業。',NULL,NULL);
