INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(15,'product',6,'highlight','en','Solid grip・Air-tight seal, locking in freshness and cleanliness');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(16,'product',7,'highlight','en','A time-saver for renovation work and everyday dust protection');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(17,'product',1,'desc','en','Featuring the Group’s patented pull-out technology, Scale Sheet offers a smarter and more convenient alternative to traditional dispensing methods. Its easy-to-use single-sheet dispensing design allows for quick and efficient access, helping save valuable operation time while providing better control over material usage and costs. Durable, non-stick, and resistant to contamination, Scale Sheet is ideal for fresh food weighing, food preparation, industrial packaging, and retail counter operations, making it a professional choice for businesses seeking greater efficiency, hygiene, and convenience.');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(18,'product',2,'desc','en',replace('A premium produce bag range for fresh food and everyday retail. Made from certified food-grade resin that is safe, odourless and highly tear-resistant. Available flat-packed or on the roll, with heat-resistant bags, double-sealed food bags and market bags to choose from, locking in moisture and freshness so shoppers and store owners can rely on every layer of food safety.\n','\n',char(10)));
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(19,'product',3,'desc','en','Produced in-house from premium Formosa Plastics resin, using automated precision extrusion and sealing at our Xingang plant in Chiayi. The range covers perforated rolls, single-sheet dispensing and Green Mark certified liners. High tensile strength and load capacity handle both household waste and the high turnover of office buildings, restaurants and hotels without splitting or leaking.');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(20,'product',4,'desc','en','Designed for convenience and fast clean-up. The one-piece draw tape closes the bag with a single pull, so waste stays inside and hands stay clean. The construction adds over 30% usable capacity while sealing odours in. Medical-grade and eco draw-tape versions are also available, keeping homes and commercial premises visibly cleaner.');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(21,'product',5,'desc','en','A multi-purpose glove range combining high elasticity with a fine surface feel. The embossed inner texture makes them easy to put on and take off without sticking, while improving grip. Powder-free and latex-free throughout, they suit food preparation and processing, everyday cleaning and home care, staying flexible, comfortable and hygienic.');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(22,'product',6,'desc','en','A series of reusable zipper bags crafted with high standards. The bags are thick and provide a solid grip, paired with a dual-track or single-track zipper structure that offers excellent airtightness and moisture resistance. Whether for freezing and preserving fresh ingredients, organizing daily items, or packaging industrial parts, they provide superior sealing protection and can withstand multiple openings and closures while remaining tight.');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(23,'product',7,'desc','en','Masking tape and dust film in one. Made for interior decoration, spray painting, home renovation and medical disinfection screening, it covers large areas fast and protects furniture, floors and walls from dust and overspray. It adheres firmly and removes without residue, cutting masking preparation time while delivering complete protection.');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(24,'product',1,'items','en','Patent certificate');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(25,'product',2,'items','en','Heat-resistant bags, Double-sealed, Food bags, Market bags, Ice bags');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(26,'product',3,'items','en','Coreless roll, Interleaved, Can Liners, ECO Garbage Bag');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(27,'product',4,'items','en','Garbage Bags, Healthcare Isolation Bags, Eco draw tape');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(28,'product',5,'items','en','Powder-free, Latex-free, Embossed texture, Easy on/off, High elasticity, Soft feel');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(29,'product',6,'items','en','Zipper bags、Freezer bags、Zipper bags、Stand-up zipper bags (self-standing)');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(30,'product',7,'items','en','Masking protection, Disinfection screening, Dust cover, Fast application');
