INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(242,'product',1,'name','ja','スケールシート（重量測定シート）');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(243,'product',1,'highlight','ja','グループ特許の単枚取り出し設計｜便利な取り扱い・汚染しにくい・衛生的');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(244,'product',1,'desc','ja','グループの特許技術を組み込んだ、抽出式のスケールシートです。従来の取り扱い方法の煩雑さと不便さを打破しました。使いやすい単枚取り出し設計で、取り扱いが簡単で、操作も便利です。作業効率の向上、取り扱い時間の短縮、使用コストの有効なコントロールを実現します。材質は強靭で、汚染に強く、粘着しにくいため、生鮮食品の計量、飲食店での準備、工業製品の小分け、商業施設のカウンターなど、様々な作業現場で使用できます。高い効率性、衛生性、利便性を追求するプロフェッショナルのための最適な選択です。');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(245,'product',1,'items','ja','特許証明書');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(246,'product',2,'name','ja','野菜・果物袋');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(247,'product',2,'highlight','ja','食品グレードの安心素材｜食材の鮮度と衛生を守る');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(248,'product',2,'desc','ja','生鮮食品や日常の小売りに最適な高品質な野菜・果物袋シリーズ。食品グレードの合格原料を厳選し、素材は安全で無毒・無味。優れた引張強度を備えている。平装・巻装など多様な規格を用意し、耐熱袋・ダブルシール食品袋・市場専用袋など多種多様な選択肢を提供。食材の水分と鮮度を効果的に保持し、消費者と商家の厳格な食品安全対策をサポート。');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(249,'product',2,'items','ja','耐熱袋、ダブルシール、食品袋、市場袋、アイスバッグ');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(250,'product',3,'name','ja','クリーニングポリ袋');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(251,'product',3,'highlight','ja','強靭で耐刺傷性・水漏れしない日常クリーニングの必需品');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(252,'product',3,'desc','ja','台湾塑膠の高品質原料を活かした自社製造の強みを生かし、嘉義新港工場の自動化精密ブロー成形・シール技術で製造。全シリーズは、ロール式・単張り抽出式・国家環境保護マーク認定クリーニングポリ袋など、様々なスタイルをカバー。優れた引張強度と耐荷重性を備え、一般家庭の日常ゴミ収集からオフィスビル・飲食店・ホテルなどの高頻度業務用現場まで、軽々と対応でき、安心して使用できる。');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(253,'product',3,'items','ja','ロール式、単張り抽出式、八つ折り袋、エコクリーニングポリ袋');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(254,'product',4,'name','ja','コード付きバッグ');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(255,'product',4,'highlight','ja','ワンプルで口を閉じ、容量が30％増加 ・ 手が汚れない');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(256,'product',4,'desc','ja','現代の利便性と効率的な清掃に特化した、貼り心地の良い商品。一体成型の丈夫なコード構造により、簡単な操作で口を閉じることができ、清掃時のゴミの漏れや手の汚れを効果的に防ぎます。特殊な設計により、内部空間の利用効率が30％以上向上し、においをしっかりと閉じ込めます。医療用とエココードのオプションもあり、家庭やオフィスの環境をより清潔で衛生的にします。');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(257,'product',4,'items','ja','清掃袋、医療袋、エココード付きバッグ');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(258,'product',5,'name','ja','多機能手套');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(259,'product',5,'highlight','ja','肌膚に優しい快適さ｜保護機能に優れた万能プロテクション手套');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(260,'product',5,'desc','ja','優れた伸縮性と繊細な感触を兼ね備えた多機能手套シリーズ。表面には特殊な内圧紋設計を採用し、着脱がスムーズで、粘着しないだけでなく、優れた滑り止めグリップ力を発揮。全シリーズがパウダーフリー、ラテックスフリーなどの肌に優しい基準を満たしており、飲食店での調理、食品加工、日常の清掃やホームケアなど、幅広いシーンで快適な衛生保護体験を提供します。');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(261,'product',5,'items','ja','パウダーフリー・ラテックスフリー・内圧紋・着脱容易・優れた伸縮性・良好な感触');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(262,'product',6,'name','ja','チャック袋');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(263,'product',6,'highlight','ja','しっかりとした手触り・密封性に優れ、鮮度と清潔さを完璧にキープ');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(264,'product',6,'desc','ja','高い水準の製造プロセスで作られた、繰り返し使えるチャック袋シリーズ。袋の本体は厚くてしっかりしており、密封性に優れたダブルトラックまたはシングルトラックのチャック構造を採用。優れた気密性と防湿性能を備えています。生鮮食品の冷凍保存、日常の小物の分類収納、工業部品の包装などに最適で、繰り返し開閉しても密封性が持続します。');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(265,'product',6,'items','ja','保存袋、冷凍袋、チャック袋、自立チャック袋（スタンドタイプ）');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(266,'product',7,'name','ja','マスキングテープ');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(267,'product',7,'highlight','ja','施工・装飾や日常の防塵に最適な時短ツール');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(268,'product',7,'desc','ja','テープと防塵フィルムが一体化した便利な保護ソリューション。室内装飾・塗装・リフォーム・医療用消毒保護のために設計されており、家具・床・壁を粉塵や塗料の飛沫から素早く・広範囲に保護します。貼り付けがしっかりしており、はがしても残留物がなく、施工前の面倒な養生作業を大幅に簡素化し、高い効率と完璧な保護効果を実現します。');
INSERT INTO "translations" ("id","entity","entity_id","field","lang","value") VALUES(269,'product',7,'items','ja','養生保護、消毒保護、粉塵被覆、施工便利');
