INSERT INTO "ui_strings" ("id","zh","page","note","hidden","zh_key","updated_by","updated_at") VALUES(4,'台塑企業、INTEPLAST USA 與長庚生技合資建立公司。以台塑品牌自製清潔袋與拉繩清潔袋，嘉義新港、越南工廠自動化生產；另有耐熱袋、夾鏈袋，以及專利抽取式 Scale Sheet。','首頁','',0,'台塑企業、INTEPLAST USA 與長庚生技合資建立公司。以台塑原料自製清潔袋與拉繩袋，嘉義新港、越南基地自動化吹膜；另有蔬果袋、夾鏈袋，以及集團專利抽取式 Scale Sheet。','admin','2026-09-10T06:24:01.250Z');
