INSERT INTO "ui_strings" ("id","zh","page","note","hidden","zh_key","updated_by","updated_at") VALUES(57,'穩定的原料資源與台塑企業嘉義新港廠區產業基礎，支撐高效率且穩定的生產配置。','關於營德','',0,'穩定的原料資源與台塑企業新港廠區產業基礎，支撐高效率且穩定的生產配置。','admin','2026-09-10T08:30:28.412Z');
