INSERT INTO "ui_strings" ("id","zh","page","note","hidden","zh_key","updated_by","updated_at") VALUES(129,'讓每一次選擇，<br>更靠近綠色生活。','永續發展','',1,'讓每一次選擇，<br>更靠近綠色生活。',NULL,NULL);
INSERT INTO "ui_strings" ("id","zh","page","note","hidden","zh_key","updated_by","updated_at") VALUES(130,'臺灣營德以通過環保標章的產品，回應日常生活對環境友善選擇的需求。從產品設計到使用，我們以可被辨識的綠色承諾，陪伴每一個乾淨安心的日常。','永續發展','',0,'臺灣營德以通過環保標章的產品，回應日常生活對環境友善選擇的需求。從產品設計到使用，我們以可被辨識的綠色承諾，陪伴每一個乾淨安心的日常。',NULL,NULL);
