INSERT INTO "ui_strings" ("id","zh","page","note","hidden","zh_key","updated_by","updated_at") VALUES(142,'原料取得、生產、銷售、使用到廢棄，各階段的減量、回收、低污染與資源效率都是重要考量。','永續發展','',0,'原料取得、生產、銷售、使用到廢棄，各階段的減量、回收、低污染與資源效率都是重要考量。',NULL,NULL);
